    "en": "Formation of pollens (B) Formation of flower (C) Formation of fruit (D) Formation of seed 2. Given below are some of the statements regarding our environment: 1 (i) Change in our life-styles have resulted in greater amounts of waste material generation. (ii) Changes in attitude have resulted in use of more disposable things. (iii) Changes in packaging has resulted in much of our waste becoming non-biodegradable. (iv) Organic farming. Which amongst these is not leading to any damage of environment? (A) (i), (ii), (iii) (B) (iv) (C) (i) and (iii) (D) (ii) and (iv) { } 3.                   1 (i)         (ii) , , /      ()       (iii)  ,   ()           (iv)            (A) (i), (ii)  (iii) (B) (ii), (iii)  (iv) (C) (i), (ii)  (iv) (D) (i), (iii)  (iv) 4.            (RRyy)       (rrYY)  ,       ()     F1        (RrYy)       F1         F2                 ? 1 (i)    (ii)    (iii)    (iv)      : (A) (i)  (ii) (B) (i)  (iv) (C) (ii)  (iv) (D) (i)  (iii) 5.     ()           : 1 (A)      (B)      (C)      (D)      { } 3. Following are the statements about the different parts of the brain. Select the correct statements. 1 (i) The thinking part of the brain is the forebrain. (ii) Centres for smell, hearing, memory, sight are located in forebrain. (iii) Salivation, vomiting, blood pressure are controlled by medulla in the hind brain. (iv) Cerebellum does not control the posture and balance of the body. (A) (i), (ii) and (iii) (B) (ii), (iii) and (iv) (C) (i), (ii) and (iv) (D) (i), (iii) and (iv) 4. Two pea plants, one with round green seeds (RRyy) and another with wrinkled yellow (rrYY) seeds were crossed with each other which produced F1 progeny that have only round yellow (RrYy) seeds. When F1 plants are self-pollinated, the F2 progeny will have which new combination of characters, as compared to the parents: 1 (i) Round, yellow (ii) Round, green (iii) Wrinkled, yellow (iv) Wrinkled, green Correct options are: (A) (i) and (ii) (B) (i) and (iv) (C) (ii) and (iv) (D) (i) and (iii) 5. In human beings the oxygen rich blood is pumped out to the body by: 1 (A) contraction of right atrium (B) relaxation of left ventricle (C) contraction of right ventricle (D) contraction of left ventricle { } 6. In terms of various trophic levels of a food chain, which of the following organisms belong to the same level? 1 (A) Snake and Grasshopper (B) Grass and tree (C) Lizard and elephant (D) Bacteria and grass 7. Opening of stomata is regulated by: 1 (A) Entry of water into guard cells (B) Exit of water from guard cells (C) Entry of air into the stomatal pore (D) Entry of water into the stomatal pore Question Nos. 8 & 9 consists of two statements: Assertion (A) and Reason (R). Answer these questions selecting the appropriate option from (A), (B), (C) and (D) given below: (A) Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A). (B) Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A). (C) Assertion (A) is true, but Reason (R) is false. (D) Assertion (A) is false, but Reason (R) is true. 8. Assertion (A): Highest percentage of pesticides is found in tertiary consumers in a food chain. 1 Reason (R): Chemicals / pesticides get accumulated progressively at each trophic level. 9. Assertion (A): Reproduction, like any other life process, is essential to maintain the life of an individual organism. 1 Reason (R): Reproduction involves creation of a DNA copy and additional cellular apparatus by the cell involved in the process. { } 10. (A) Varun is diabetic. His latest ultrasound reports showed a blockage in his pancreatic duct. How will this affect the dual functioning of the pancreas?",
